from _lib import File
F=File('pre2020_gaps4','o-gt','Fourth fill of uncovered pre-2020 off-road years from model-year spec and change listings: KTM 250/300 XC, Husqvarna FE 450/501, TE 150, TX 125, Yamaha WR250F (knowledge push 2026-11)','KTM',['250 XC'],list(range(2011,2020)))
R=F.R; K='KTM'; Q='Husqvarna'; A='article'
s=F.src(A,"Total Motorcycle - 2013 KTM 250 XC","https://www.totalmotorcycle.com/motorcycles/2013models/2013-KTM-250XC","2013")
R('identity','250 XC 2013 updates and specs',['250 XC'],[2013],"For 2013 the 250 XC got a revised clutch, optimised engine-to-frame braces, new US cross-country settings in the 48 mm closed-cartridge fork, a lower triple clamp 80 g lighter, a 25 mm rear axle in place of the 20 mm one, and restyled bodywork with a rib-free front fender. It is a 249 cc (66.4 x 72 mm) two-stroke with kick and electric start, a six-speed gearbox and hydraulic clutch. Travel is 300 mm front and 317 mm rear, the seat is 992 mm and it weighs about 229 lb without fuel. US list price $8,199.",{'rear_axle_mm':'25 (was 20)','travel_mm':'300 / 317','seat_mm':992,'weight_lb_no_fuel':229,'msrp_usd':8199},'OEM',s,make=K)
s=F.src(A,"Total Motorcycle - 2013 KTM 300 XC","https://www.totalmotorcycle.com/motorcycles/2013models/2013-KTM-300XC","2013")
R('identity','300 XC 2013 updates and specs',['300 XC'],[2013],"For 2013 the 300 XC got the new DDS clutch (a single diaphragm spring with a steel basket and thin steel plates), a V-Force reed cage, new US cross-country settings in the 48 mm closed-cartridge fork, a lighter lower triple clamp, a 25 mm rear axle in place of the 20 mm one and restyled bodywork. It is a 293 cc (72 x 72 mm) two-stroke with kick and electric start and a six-speed gearbox. Travel is 300 mm front and 317 mm rear and it weighs about 229 lb without fuel. US list price $8,299.",{'clutch':'DDS diaphragm','rear_axle_mm':'25 (was 20)','travel_mm':'300 / 317','weight_lb_no_fuel':229,'msrp_usd':8299},'OEM',s,make=K)
s=F.src(A,"TopSpeed - 2015 KTM 250 XC","https://www.topspeed.com/motorcycles/motorcycle-reviews/ktm/2015-ktm-250-xc-ar168506/pictures.html","2015")
R('identity','250 XC 2015 updates and specs',['250 XC'],[2015],"For 2015 the 250 XC got a 4CS fork 8 mm longer with a new hydraulic stop, new cartridge pistons and a 20 N/mm chamber spring (was 18), a re-valved shock with 4 mm more stroke on a new linkage with a higher starting rate, a 22 mm front axle in place of the 26 mm one, a lighter clutch basket, shorter starter gearing with a new 3 Ah battery and a redesigned reed housing. Final drive is 13/50, the tank holds 10 litres, the seat is 992 mm and it weighs 103.9 kg without fuel.",{'fork_chamber_spring':'20 N/mm (was 18)','front_axle_mm':'22 (was 26)','gearing':'13/50','tank_l':10,'weight_kg_no_fuel':103.9},'OEM',s,make=K)
s=F.src(A,"Total Motorcycle - 2016 KTM 250 XC","https://www.totalmotorcycle.com/motorcycles/2016/2016-KTM-250-XC/","2016")
R('identity','250 XC 2016 updates and specs',['250 XC'],[2016],"The 2016 250 XC kept the 2015 chassis and engine with detail changes: rubber damping in the upper triple clamp and bar mounts (two bar positions) to cut vibration, a larger bar pad and lighter wave brake discs. It runs a Keihin PWK 38 carburettor, six-speed gearbox, kick and electric start, DDS clutch with Brembo hydraulics, a 48 mm WP 4CS fork and linkage shock (300 / 317 mm travel), a 10-litre tank and weighs 100.7 kg without fuel.",{'carb':'Keihin PWK 38S AG','fork':'WP 4CS 48 mm','tank_l':10,'weight_kg_no_fuel':100.7},'OEM',s,make=K)
s=F.src(A,"TopSpeed - 2016 Husqvarna FE 450 and FE 501","https://www.topspeed.com//motorcycles/motorcycle-reviews/husqvarna/2016-husqvarna-fe-450-fe-501-fe-501-s-ar170878/pictures.html","2016")
R('identity','FE 450 and FE 501 2016 updates and specs',['FE 450','FE 501'],[2016],"For 2016 the FE 450 and FE 501 got a 22 mm front axle in place of the 26 mm one, 22 mm offset triple clamps with revised front geometry, new brakes (260 mm front, 220 mm rear), lighter spokes, a lighter clutch basket and a grippier seat cover. Both have a six-speed gearbox, DDS clutch with Brembo hydraulics, a 48 mm WP 4CS fork (11.8 in travel), a linkage shock (13 in), a 2.25-gallon tank and a 38.2 in seat. The maker lists 53 hp and 248.7 lb without fuel for the FE 450 and 58 hp and 249.8 lb for the FE 501. List prices $9,999 and $10,199.",{'front_axle_mm':'22 (was 26)','claimed_hp':'53 / 58','weight_lb_no_fuel':'248.7 / 249.8','tank_gal':2.25,'seat_in':38.2,'msrp_usd':'9,999 / 10,199'},'OEM',s,make=Q)
s=F.src(A,"Total Motorcycle - 2017 Husqvarna TE 150","https://www.totalmotorcycle.com/motorcycles/2017/2017-Husqvarna-TE150","2017")
R('identity','TE 150 2017: new model',['TE 150'],[2017],"The 2017 TE 150 has an all-new, more compact two-stroke engine (58 x 54.4 mm) with a redesigned power valve and crankcases about 600 g lighter, electric start as standard with a kick backup, and a 38 mm Mikuni TMX in place of the Keihin. The frame is 0.6 kg lighter, the composite subframe 1 kg lighter, and it uses the WP Xplor 48 fork (300 mm travel) and a linkage shock (330 mm). It has a six-speed gearbox, Magura hydraulic clutch, a 10-litre tank, a 960 mm seat and weighs 92.0 kg without fuel.",{'bore_stroke_mm':'58 x 54.4','carb':'Mikuni TMX 38','weight_kg_no_fuel':92.0,'seat_mm':960,'tank_l':10},'OEM',s,make=Q)
s=F.src(A,"MotorcycleDB - 2017 Husqvarna TX 125 specifications","https://www.motorcycledb.com/Husqvarna_TX_125_2017/46068","2017")
R('identity','TX 125 2017 layout',['TX 125'],[2017],"The 2017 TX 125 is a 124.8 cc (54.0 x 54.5 mm) kick-start two-stroke with a six-speed gearbox and hydraulic clutch. It uses the WP Xplor 48 fork with preload adjusters (300 mm travel) and a linkage shock (330 mm), a 10-litre (2.64-gallon) tank, a 960 mm seat, a 21-inch front and 18-inch rear wheel, and weighs 92.2 kg dry.",{'bore_stroke_mm':'54.0 x 54.5','starter':'kick','fork':'WP Xplor 48','dry_weight_kg':92.2,'tank_l':10,'seat_mm':960},'OEM',s,'low',make=Q)
s=F.src(A,"Total Motorcycle - 2011 Yamaha WR250F","https://www.totalmotorcycle.com/photos/2011models/2011-Yamaha-WR250F.htm","2011")
R('identity','WR250F 2011 layout (carbureted five-valve)',['WR250F'],[2011],"The 2011 WR250F is a five-titanium-valve DOHC 250 (12.5:1) with a 37 mm Keihin FCR flat-slide, electric start with a kick backup and a five-speed gearbox, with a 48 mm Kayaba cartridge fork (11.8 in travel) and linkage shock (12.2 in). Seat height 38.6 in, 2.1-gallon tank, 256 lb wet by the US spec table. US list price $6,850.",{'carb':'Keihin FCR 37','valves':5,'gearbox':'5-speed','seat_in':38.6,'tank_gal':2.1,'wet_weight_lb':256,'msrp_usd':6850},'OEM',s,make='Yamaha')
s=F.src(A,"Total Motorcycle - 2013 Yamaha WR250F","https://www.totalmotorcycle.com/motorcycles/2013models/2013-Yamaha-WR250F","2013")
R('identity','WR250F 2013 layout (carbureted five-valve)',['WR250F'],[2013],"The 2013 WR250F is a five-titanium-valve DOHC 249 cc engine (12.5:1) with a 37 mm Keihin FCR flat-slide, electric start with a kick backup and a five-speed gearbox, with a 48 mm Kayaba cartridge fork (11.8 in travel) and linkage shock (12.2 in). Seat height 38.6 in, 2.1-gallon tank, 254 lb wet by the US spec. US list price $6,990.",{'carb':'Keihin FCR 37','valves':5,'gearbox':'5-speed','seat_in':38.6,'tank_gal':2.1,'wet_weight_lb':254,'msrp_usd':6990},'OEM',s,make='Yamaha')
if __name__=='__main__': F.write()
